// 手机诊断上报（2026-09-05 临时）：PHONE_DIAG_SCRIPT 的落点。置於认证之前——
// 即使 cookie 状态坏了也能收到报告。仅追加 ≤2MB 日志，满了停写。
if (req.method === 'POST' && req.url?.startsWith('/pocket-diag')) {
  let body = '';
  req.on('data', (c) => { body += c; if (body.length > 96 * 1024) req.destroy(); });
  req.on('end', () => {
    try {
      if (DIAG_LOG_PATH !== null) {
        let writable = true;
        try { writable = !existsSync(DIAG_LOG_PATH) || statSync(DIAG_LOG_PATH).size < 2 * 1024 * 1024; } catch { writable = true; }
        if (writable) appendFileSync(DIAG_LOG_PATH, `${new Date().toISOString()} ${clientIp(req)} ${body}\n`);
      }
    } catch { /* 诊断失败不影响页面 */ }
    res.writeHead(204, { 'cache-control': 'no-store' });
    res.end();
  });
  return;
}
